using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly string baseUrl;

    private int status = 200;
    private string responseBody = """{"status":"approved"}""";

    public string? ReceivedMethod { get; private set; }
    public string? ReceivedPath { get; private set; }
    public string? ReceivedContentType { get; private set; }
    public string? ReceivedBody { get; private set; }

    public HttpPaymentGatewayTests()
    {
        var port = FreePort();
        baseUrl = $"http://127.0.0.1:{port}";
        listener.Prefixes.Add(baseUrl + "/");
        listener.Start();
        _ = Task.Run(Serve);
        client = new HttpClient { BaseAddress = new Uri(baseUrl) };
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.Equal("POST", ReceivedMethod);
        Assert.Equal("/v1/authorizations", ReceivedPath);
        Assert.StartsWith("application/json", ReceivedContentType);
        using var json = JsonDocument.Parse(ReceivedBody!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        responseBody = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        responseBody = """{"id":"a1","status":"approved","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline_even_with_an_approved_looking_body()
    {
        status = 402;
        responseBody = """{"status":"approved"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_with_an_empty_body_is_a_decline()
    {
        status = 402;
        responseBody = "";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_exactly_approved_is_never_treated_as_approved(string body)
    {
        responseBody = body;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_rather_than_decisions(int code)
    {
        status = code;
        responseBody = """{"status":"declined"}""";
        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)code, error.StatusCode);
    }

    [Theory]
    [InlineData("not json")]
    [InlineData("")]
    public async Task A_success_answer_that_is_not_valid_json_fails_loudly(string body)
    {
        responseBody = body;
        await Assert.ThrowsAnyAsync<Exception>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext context;
            try { context = await listener.GetContextAsync(); }
            catch { return; }

            ReceivedMethod = context.Request.HttpMethod;
            ReceivedPath = context.Request.Url!.AbsolutePath;
            ReceivedContentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                ReceivedBody = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = status;
            context.Response.ContentType = "application/json";
            context.Response.ContentLength64 = bytes.Length;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private static int FreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
